@Service
public class PaymentReconciliationService {
    public void reconcile() {
        List<Payment> gatewayPayments = paymentGateway.fetchDailyTransactions();
        for (Payment p : gatewayPayments) {
            if (!orderRepository.existsByTransactionId(p.getId())) {
                log.error("Discrepancy found: Payment {} exists but Order missing. Triggering compensation.", p.getId());
                paymentGateway.refund(p.getId());
            }
        }
    }
}
